"""Turn the saved experiment into report materials, without creating a formal report."""
import hashlib
import json
from pathlib import Path
from rag import ROOT, read_json

def run():
    m = read_json(ROOT / 'results' / 'metrics.json')
    bench = read_json(ROOT / 'results' / 'retrieval_benchmark.json')
    tuning = read_json(ROOT / 'results' / 'tuning.json')
    env = read_json(ROOT / 'results' / 'environment.json')
    answers = read_json(ROOT / 'results' / 'answers.json')
    validation = read_json(ROOT / 'results' / 'validation.json')
    text = ['# Матеріали до майбутнього звіту ЛР7', '', 'Дата виконання: 16.10.2026. Оформлений звіт DOCX/PDF не створювався.', '', '## Що реалізовано', '', 'Тематика ЛР1: енергетика / програмне забезпечення / візуалізація. Локальний RAG: multilingual-e5-small → FAISS + TF-IDF → top-k і фільтр → Qwen3-0.6B. Моделі використовують CPU. Джерела — матеріали попередніх робіт; корпус містить 88 фрагментів зі сталими ID та походженням.', '', 'Схема: `figures/01_rag_architecture.png` та редагований векторний SVG. Опис компонентів, формули пошуку, запуск та первинні джерела — `README.md`.', '', '## Оптимізація пошуку', '', 'Перевірено 99 конфігурацій на 12 dev-запитах. Test-набір не використаний для вибору параметрів. Вибір dev: `' + json.dumps(m['selected_config'],ensure_ascii=False) + '`.', '', f"Dev retrieval success: {tuning['selected']['retrieval_success_rate']:.3f}; recall: {tuning['selected']['recall']:.3f}; precision: {tuning['selected']['precision']:.3f}. Це оцінки налаштування, а не фінального тесту.", '', '## Окремий тест пошуку', '', '15 test-запитів: 12 з відповіддю у базі, 3 без неї. Recall, precision і MRR обчислені на 12 позитивних запитах. Для невідомих запитів окремо перевірена відмова пошуку.', '', '| Умова | Recall | Precision | MRR | Відмова пошуку на невідомі | Пошуковий успіх загалом |', '|---|---:|---:|---:|---:|---:|']
    for name in ['baseline','optimized']:
        r=m['conditions'][name]['retrieval']
        text.append(f"| {name} | {r['recall']:.3f} | {r['precision']:.3f} | {r['mrr']:.3f} | {r['unknown_rejection_rate']:.3f} | {r['retrieval_success_rate']:.3f} |")
    text += ['', '## Генерація: автоматичні поверхневі перевірки', '', 'Виконано 45 умов запуску: 15 питань × 3 умови. Коли пошук не повернув контекст, відповідь відмови сформовано без виклику LLM; це явно записано в `generator_called`. Усі інші відповіді згенеровані справжньою локальною LLM. Повні необроблені тексти — `results/answers.jsonl`.', '', '| Умова | Факти за шаблонами, усі 15 | Факти за шаблонами, 12 відомих | Відмови LLM/фільтра на 3 невідомі | Валідні ID на 12 відомих | Середній час генерації, с |', '|---|---:|---:|---:|---:|---:|']
    for name,c in m['conditions'].items():
        text.append(f"| {name} | {c['answer_fact_pattern_accuracy']:.3f} | {c['answerable_fact_pattern_accuracy']:.3f} | {c['unknown_refusal_rate']:.3f} | {c['valid_citation_rate_answerable']:.3f} | {c['mean_generation_ms']/1000:.2f} |")
    text += ['', '**Це не повна семантична точність.** Шаблони можуть пропустити перефразування або зарахувати неповну відповідь. Наприклад, t06/optimized містить правильне твердження про відсутній атрибут, але не містить слова «відкритий», тому автоматичний шаблон не пройдено. t06/baseline містить фразу про відкритий світ разом із зайвою відмовою і може пройти шаблон. t14/baseline перефразував відмову, тому точний автоматичний детектор може її не впізнати. Ці випадки видно у сирих відповідях.', '', '## Швидкість', '', '| Умова | Медіана пошуку, мс | P95 пошуку, мс | Кількість вимірювань |', '|---|---:|---:|---:|']
    for name,b in bench.items():
        text.append(f"| {name} | {b['p50_ms']:.2f} | {b['p95_ms']:.2f} | {b['repetitions']*b['queries_per_repetition']} |")
    text += ['', 'Пошук включає енкодер запиту, FAISS, лексичне оцінювання й фільтрацію. Завантаження моделей і генерація не входять. Вимірювання після прогріву: п’ять проходів по 15 запитах. Відмінність у десяті частки мілісекунди не є доказом прискорення. Менший top-k скорочує контекст і може зменшувати час генерації, але не гарантує кращу відповідь.', '', '## Приклади, які варто включити до звіту', '']
    for qid,cond,comment in [
        ('t02','optimized','Правильне фактичне значення і правильний ID джерела.'),
        ('t03','optimized','Генерація поєднує формулу погодинної енергії з правилом виключення неповних годин.'),
        ('t05','baseline','Точні прогноз і факт з попереднього експерименту.'),
        ('t05','optimized','Числа правильні, але модель вигадала ID lab5.fact. Реальний контекст — lab5.forecast.'),
        ('t01','optimized','top-k=1 повернув загальне пояснення KDD замість числового фрагмента lab1.split; відповідь неповна, ID вигаданий.'),
        ('t07','optimized','Потрібне джерело знайдено, але LLM відповіла HermiT замість ForecastVisualization. Це помилка генерації.'),
        ('t08','optimized','Модель відмовилася, хоча шість полів явно подані у знайденому фрагменті.'),
        ('t13','optimized','Відмова без генерації, оскільки після фільтрації не залишилося фрагментів.'),
        ('t14','optimized','Близькість питання до енергетики не означає наявність тарифу. Перевірити фактичний текст відповіді нижче.'),
        ('t15','optimized','Семантично близький клас Household не містить пароля Wi-Fi. Це перевірка поведінки за відсутності факту.'),
    ]:
        r=next(r for r in answers if r['id']==qid and r['condition']==cond)
        text += [f"### {qid} / {cond}", '', r['question'], '', '> ' + r['answer'].replace('\n','\n> '), '', comment, '', 'Переданий контекст: ' + (', '.join(p['id'] for p in r['passages']) or 'немає') + '.', '']
    text += ['## Висновки, які підтримуються доказами', '', '- Додатковий контекст дозволив відтворювати конкретні числа з попередніх лабораторних; без контексту компактна модель їх не знає і часто вигадує.', '- Вибір найкращого пошуку на dev не гарантує покращення генерації на test. top-k=1 втратив потрібний числовий фрагмент у t01; baseline top-3 його містив.', '- Помилки пошуку та помилки генерації слід розрізняти: t07 і t08 мають релевантний контекст, проте неправильні або відсутні відповіді.', '- Маленька Qwen3-0.6B може вигадувати ID джерел. Потрібно порівнювати посилання з полем passages; автоматична перевірка ID не замінює перевірки підтримки тверджень.', '- Фільтр успішно відхилив t13, але пропустив тематично близькі t14 і t15. Самої cosine similarity недостатньо для надійного визначення наявності відповіді.', '- Для наступного покращення потрібні більша локальна інструктивна модель, окремий dev-набір для підказки генератора, перевірка цитат та розширення тестів. Ці зміни не видаються за вже проведені експерименти.', '', '## Перевірка та відтворюваність', '', f"Перевірка артефактів: пройдено {validation['passed']}, помилок {validation['failed']}. Перевірені SHA-256 джерел, походження фрагментів, збережені числа, нормування векторів, відповідність FAISS незалежним скалярним добуткам, dev/test, повнота 45 записів, контекст, пороги, логи та повторний розрахунок метрик.", '', 'Середовище: Python ' + env['python'] + '; пакети та налаштування — `results/environment.json`. Ревізії моделей:', '']
    for model,data in env['models'].items():text.append('- ' + data['repo'] + ' @ `' + data['revision'] + '`')
    text += ['', 'SHA-256 файлу з усіма відповідями: `' + hashlib.sha256((ROOT / 'results' / 'answers.json').read_bytes()).hexdigest() + '`.', '', '## Карта матеріалів за завданням', '', '| Вимога | Доказ |', '|---|---|', '| Архітектура й компоненти RAG | README; figures/01_rag_architecture.png, .svg |', '| Інтеграція реальної локальної LLM | rag.py/Generator; models/metadata.json; відповіді з input/output_tokens |', '| Власна база знань | inputs; knowledge/chunks.json, sources.json |', '| Query Encoder і FAISS | rag.py/Encoder, Retriever; embeddings.npy; index.faiss |', '| top-k і фільтрація | tuning.csv, tuning.json, selected_config.json |', '| Типові та невідомі запити | evaluation/queries.json |', '| Порівняння очікуваних і отриманих результатів | retrieval_test.json; answers.json; metrics.json; приклади вище |', '| Швидкість пошуку й генерації | retrieval_benchmark.json; answers.json; environment.json |', '| Матеріали для рисунків і прикладів | figures; results/demo.html; run.log |', '', 'Новий оформлений звіт буде окремим етапом. Не називати поверхневу перевірку шаблонів повною точністю відповідей і не приховувати невдалі приклади.', '']
    (ROOT / 'REPORT_MATERIALS.md').write_text('\n'.join(text),encoding='utf-8')
    print('REPORT_MATERIALS.md saved.')

if __name__=='__main__':
    run()
